+func TestCustomTypeNoEllipsis(t *testing.T) {
+	type CLI struct {
+		Flag []byte `type:"existingfile"`
+	}
+	var cli CLI
+	p := mustNew(t, &cli, kong.Exit(func(int) {}))
+	w := &strings.Builder{}
+	p.Stderr = w
+	p.Stdout = w
+	_, err := p.Parse([]string{"--help"})
+	assert.NoError(t, err)
+	help := w.String()
+	assert.NotContains(t, help, "...")
+}
